using System;
using System.Runtime.InteropServices;
using System.Threading;
using System.Collections.Generic;
using Microsoft.Build.Framework;
using Microsoft.Build.Utilities;
using System.Windows.Forms;
using System.Drawing;
using System.Drawing.Drawing2D;
using System.Linq;
using System.Diagnostics;

public class ClassExample : Task
{
    [DllImport("user32.dll")]
    static extern void mouse_event(uint dwFlags, uint dx, uint dy, uint dwData, int dwExtraInfo);

    [DllImport("user32.dll")]
    static extern short GetAsyncKeyState(int vKey);

    [DllImport("user32.dll")]
    static extern void keybd_event(byte bVk, byte bScan, uint dwFlags, int dwExtraInfo);

    [DllImport("user32.dll")]
    static extern IntPtr GetForegroundWindow();

    [DllImport("user32.dll")]
    static extern uint GetWindowThreadProcessId(IntPtr hWnd, out uint lpdwProcessId);

    const uint MOUSEEVENTF_LEFTDOWN = 0x0002;
    const uint MOUSEEVENTF_LEFTUP = 0x0004;
    const uint MOUSEEVENTF_RIGHTDOWN = 0x0008;
    const uint MOUSEEVENTF_RIGHTUP = 0x0010;
    const uint KEYEVENTF_KEYUP = 0x0002;

    static bool running = false;
    static Dictionary<string, bool> activeModules = new Dictionary<string, bool>();
    static Dictionary<string, ModuleConfig> moduleConfigs = new Dictionary<string, ModuleConfig>();
    static Dictionary<string, Thread> moduleThreads = new Dictionary<string, Thread>();
    static bool inventoryTotemActive = false;
    static bool hasTotemInOffhand = false;

    static Dictionary<string, int> keyMap = new Dictionary<string, int>() {
        {"1", 0x31}, {"2", 0x32}, {"3", 0x33}, {"4", 0x34}, {"5", 0x35},
        {"6", 0x36}, {"7", 0x37}, {"8", 0x38}, {"9", 0x39}, {"0", 0x30},
        {"a", 0x41}, {"b", 0x42}, {"c", 0x43}, {"d", 0x44}, {"e", 0x45},
        {"f", 0x46}, {"g", 0x47}, {"h", 0x48}, {"i", 0x49}, {"j", 0x4A},
        {"k", 0x4B}, {"l", 0x4C}, {"m", 0x4D}, {"n", 0x4E}, {"o", 0x4F},
        {"p", 0x50}, {"q", 0x51}, {"r", 0x52}, {"s", 0x53}, {"t", 0x54},
        {"u", 0x55}, {"v", 0x56}, {"w", 0x57}, {"x", 0x58}, {"y", 0x59},
        {"z", 0x5A},
        {"f1", 0x70}, {"f2", 0x71}, {"f3", 0x72}, {"f4", 0x73},
        {"f5", 0x74}, {"f6", 0x75}, {"f7", 0x76}, {"f8", 0x77}, 
        {"f9", 0x78}, {"f10", 0x79}, {"f11", 0x7A}, {"f12", 0x7B},
        {"mouse4", 0x05}, {"mouse5", 0x06},
        {"tab", 0x09}, {"shift", 0x10}, {"ctrl", 0x11}, {"alt", 0x12},
        {"space", 0x20}, {"enter", 0x0D}, {"esc", 0x1B}, {"backspace", 0x08},
        {"capslock", 0x14}, {"insert", 0x2D}, {"delete", 0x2E}, 
        {"home", 0x24}, {"end", 0x23}, {"pageup", 0x21}, {"pagedown", 0x22},
        {"left", 0x25}, {"up", 0x26}, {"right", 0x27}, {"down", 0x28},
        {",", 0xBC}, {".", 0xBE}, {";", 0xBA}, {"'", 0xDE},
        {"[", 0xDB}, {"]", 0xDD}, {"-", 0xBD}, {"=", 0xBB},
        {"/", 0xBF}, {"\\", 0xDC}, {"`", 0xC0}
    };

    class ModuleConfig
    {
        public string Keybind;
        public int KeybindCode;
        public int Slot1;
        public int Slot2;
        public int Slot3;
        public int Delay;
        public int DelayMs1;
        public int DelayMs2;
        public int DelayMs3;
        public int DelayMs4;
        public int DelayMs5;
        public int DelayMs6;
    }

    static bool IsMinecraftFocused()
    {
        try
        {
            IntPtr hWnd = GetForegroundWindow();
            if (hWnd == IntPtr.Zero) return false;

            uint processId;
            GetWindowThreadProcessId(hWnd, out processId);

            if (processId == 0) return false;

            Process process = Process.GetProcessById((int)processId);
            string processName = process.ProcessName.ToLower();

            return processName == "javaw" || processName == "java";
        }
        catch
        {
            return false;
        }
    }

    static void ClickRight()
    {
        mouse_event(MOUSEEVENTF_RIGHTDOWN, 0, 0, 0, 0);
        mouse_event(MOUSEEVENTF_RIGHTUP, 0, 0, 0, 0);
    }

    static void ClickLeft()
    {
        mouse_event(MOUSEEVENTF_LEFTDOWN, 0, 0, 0, 0);
        mouse_event(MOUSEEVENTF_LEFTUP, 0, 0, 0, 0);
    }

    static void PressKey(int vkCode)
    {
        keybd_event((byte)vkCode, 0, 0, 0);
        keybd_event((byte)vkCode, 0, KEYEVENTF_KEYUP, 0);
    }

    static bool IsKeyPressed(int vkCode)
    {
        return (GetAsyncKeyState(vkCode) & 0x8000) != 0;
    }

    static int GetVKCode(string key)
    {
        key = key.ToLower().Trim();
        if (keyMap.ContainsKey(key))
            return keyMap[key];
        return 0;
    }

    static void RunInventoryTotem()
    {
        bool lastEState = false;
        int checkCounter = 0;

        while (inventoryTotemActive)
        {
            bool ePressed = IsKeyPressed(0x45); // E key

            if (ePressed && !lastEState)
            {
                // Verifica se Minecraft è in primo piano
                if (IsMinecraftFocused())
                {
                    // Apri inventario
                    Thread.Sleep(50);

                    // Premi 1 per selezionare il totem (slot 1)
                    PressKey(0x31); // 1 key
                    Thread.Sleep(30);

                    // Premi F per spostare nell'offhand
                    PressKey(0x46); // F key
                    Thread.Sleep(30);

                    // Chiudi inventario premendo E
                    PressKey(0x45); // E key
                    Thread.Sleep(30);
                }
            }

            lastEState = ePressed;
            Thread.Sleep(10);
        }
    }

    static int GetSlotKeyCode(int slot)
    {
        switch(slot)
        {
            case 1: return 0x31;
            case 2: return 0x32;
            case 3: return 0x33;
            case 4: return 0x34;
            case 5: return 0x35;
            case 6: return 0x36;
            case 7: return 0x37;
            case 8: return 0x38;
            case 9: return 0x39;
            default: return 0x31;
        }
    }

    static void RunAirplace(ModuleConfig config)
    {
        bool lastState = false;

        while (activeModules.ContainsKey("airplace") && activeModules["airplace"])
        {
            bool currentState = IsKeyPressed(config.KeybindCode);

            if (currentState && !lastState && IsMinecraftFocused())
            {
                PressKey(config.Slot1);
                ClickRight();
                Thread.Sleep(config.DelayMs1 > 0 ? config.DelayMs1 : 65);

                PressKey(config.Slot2);
                ClickRight();
                Thread.Sleep(config.DelayMs2 > 0 ? config.DelayMs2 : 70);

                PressKey(config.Slot3);
                ClickRight();
                Thread.Sleep(config.DelayMs3 > 0 ? config.DelayMs3 : 50);

                PressKey(config.Slot1);
                ClickRight();
                Thread.Sleep(config.DelayMs4 > 0 ? config.DelayMs4 : 65);

                PressKey(config.Slot2);
                ClickRight();
                Thread.Sleep(config.DelayMs5 > 0 ? config.DelayMs5 : 70);

                PressKey(config.Slot3);
                ClickRight();
                Thread.Sleep(config.DelayMs6 > 0 ? config.DelayMs6 : 50);
            }

            lastState = currentState;
            Thread.Sleep(1);
        }
    }

    static void RunSingle(ModuleConfig config)
    {
        bool lastState = false;

        while (activeModules.ContainsKey("single") && activeModules["single"])
        {
            bool currentState = IsKeyPressed(config.KeybindCode);

            if (currentState && !lastState && IsMinecraftFocused())
            {
                PressKey(config.Slot1);
                ClickRight();
                Thread.Sleep(config.DelayMs1 > 0 ? config.DelayMs1 : config.Delay);

                PressKey(config.Slot2);
                ClickRight();
                Thread.Sleep(config.DelayMs2 > 0 ? config.DelayMs2 : config.Delay);

                PressKey(config.Slot3);
                ClickRight();
                Thread.Sleep(config.DelayMs3 > 0 ? config.DelayMs3 : config.Delay);
            }

            lastState = currentState;
            Thread.Sleep(1);
        }
    }

    static void RunDouble(ModuleConfig config)
    {
        bool lastState = false;

        while (activeModules.ContainsKey("double") && activeModules["double"])
        {
            bool currentState = IsKeyPressed(config.KeybindCode);

            if (currentState && !lastState && IsMinecraftFocused())
            {
                PressKey(config.Slot1);
                ClickRight();
                Thread.Sleep(config.DelayMs1 > 0 ? config.DelayMs1 : config.Delay);

                PressKey(config.Slot2);
                ClickRight();
                Thread.Sleep(config.DelayMs2 > 0 ? config.DelayMs2 : config.Delay);

                PressKey(config.Slot3);
                ClickRight();
                Thread.Sleep(config.DelayMs3 > 0 ? config.DelayMs3 : config.Delay);

                PressKey(config.Slot1);
                ClickRight();
                Thread.Sleep(config.DelayMs4 > 0 ? config.DelayMs4 : config.Delay);

                PressKey(config.Slot2);
                ClickRight();
                Thread.Sleep(config.DelayMs5 > 0 ? config.DelayMs5 : config.Delay);

                PressKey(config.Slot3);
                ClickRight();
                Thread.Sleep(config.DelayMs6 > 0 ? config.DelayMs6 : config.Delay);
            }

            lastState = currentState;
            Thread.Sleep(1);
        }
    }

    static void RunHitCrystal(ModuleConfig config)
    {
        bool lastState = false;
        bool isExecuting = false;

        while (activeModules.ContainsKey("hitcrystal") && activeModules["hitcrystal"])
        {
            bool currentState = IsKeyPressed(config.KeybindCode);

            if (!currentState && lastState)
            {
                isExecuting = false;
            }

            if (currentState && !lastState && !isExecuting && IsMinecraftFocused())
            {
                isExecuting = true;

                PressKey(config.Slot2);
                Thread.Sleep(5);
                ClickRight();
                Thread.Sleep(config.DelayMs1 > 0 ? config.DelayMs1 : 45);

                PressKey(config.Slot1);
                Thread.Sleep(config.DelayMs2 > 0 ? config.DelayMs2 : 10);

                while (IsKeyPressed(config.KeybindCode) && activeModules.ContainsKey("hitcrystal") && activeModules["hitcrystal"] && IsMinecraftFocused())
                {
                    ClickRight();
                    Thread.Sleep(config.DelayMs3 > 0 ? config.DelayMs3 : 18);
                    ClickLeft();
                    Thread.Sleep(config.DelayMs4 > 0 ? config.DelayMs4 : 18);
                }

                isExecuting = false;
            }

            lastState = currentState;
            Thread.Sleep(1);
        }
    }

    public override bool Execute()
    {
        Application.EnableVisualStyles();
        Application.SetCompatibleTextRenderingDefault(false);

        var form = new MacroForm();
        Application.Run(form);

        return true;
    }

    class MacroForm : Form
    {
        private Panel airplacePanel, singlePanel, doublePanel, hitcrystalPanel, totemPanel;
        private Color cardColor = Color.FromArgb(30, 30, 30);
        private Color activeColor = Color.FromArgb(60, 60, 60);
        private Color successColor = Color.FromArgb(40, 167, 69);

        public MacroForm()
        {
            this.Text = "Areola Macro";
            this.Size = new Size(900, 550);
            this.StartPosition = FormStartPosition.CenterScreen;
            this.BackColor = Color.FromArgb(20, 20, 20);
            this.FormBorderStyle = FormBorderStyle.FixedDialog;
            this.MaximizeBox = false;
            this.MinimizeBox = true;

            InitializeComponents();
        }

        private void InitializeComponents()
        {
            var headerLabel = new Label();
            headerLabel.Text = "AREOLA MACRO";
            headerLabel.Font = new Font("Segoe UI", 24, FontStyle.Bold);
            headerLabel.ForeColor = Color.White;
            headerLabel.AutoSize = true;
            headerLabel.Location = new Point(330, 20);
            this.Controls.Add(headerLabel);

            var subtitleLabel = new Label();
            subtitleLabel.Text = "Professional Minecraft Automation";
            subtitleLabel.Font = new Font("Segoe UI", 10, FontStyle.Italic);
            subtitleLabel.ForeColor = Color.FromArgb(150, 150, 150);
            subtitleLabel.AutoSize = true;
            subtitleLabel.Location = new Point(355, 55);
            this.Controls.Add(subtitleLabel);

            airplacePanel = CreateModuleCard("Airplace Mode", 30, 100, "airplace");
            singlePanel = CreateModuleCard("Single Anchor", 200, 100, "single");
            doublePanel = CreateModuleCard("Double Anchor", 370, 100, "double");
            hitcrystalPanel = CreateModuleCard("Hit Crystal", 540, 100, "hitcrystal");
            totemPanel = CreateTotemCard("Inventory Totem", 710, 100);

            this.Controls.Add(airplacePanel);
            this.Controls.Add(singlePanel);
            this.Controls.Add(doublePanel);
            this.Controls.Add(hitcrystalPanel);
            this.Controls.Add(totemPanel);
        }

        private Panel CreateTotemCard(string name, int x, int y)
        {
            var panel = new Panel();
            panel.Location = new Point(x, y);
            panel.Size = new Size(160, 220);
            panel.BackColor = cardColor;
            panel.BorderStyle = BorderStyle.None;
            panel.Cursor = Cursors.Hand;

            var nameLabel = new Label();
            nameLabel.Text = name;
            nameLabel.Font = new Font("Segoe UI", 11, FontStyle.Bold);
            nameLabel.ForeColor = Color.White;
            nameLabel.AutoSize = false;
            nameLabel.Size = new Size(140, 60);
            nameLabel.Location = new Point(10, 20);
            nameLabel.TextAlign = ContentAlignment.TopCenter;

            var statusDot = new Label();
            statusDot.Size = new Size(15, 15);
            statusDot.BackColor = Color.FromArgb(60, 60, 60);
            statusDot.Location = new Point(25, 130);
            statusDot.Tag = "statusdot";

            var statusText = new Label();
            statusText.Text = "Inactive";
            statusText.Font = new Font("Segoe UI", 9);
            statusText.ForeColor = Color.FromArgb(150, 150, 150);
            statusText.AutoSize = true;
            statusText.Location = new Point(45, 128);
            statusText.Tag = "statustext";

            var infoLabel = new Label();
            infoLabel.Text = "Slot 1 → Offhand";
            infoLabel.Font = new Font("Segoe UI", 8);
            infoLabel.ForeColor = Color.FromArgb(150, 150, 150);
            infoLabel.AutoSize = true;
            infoLabel.Location = new Point(45, 148);
            infoLabel.Tag = "info";

            var configBtn = new Button();
            configBtn.Text = "CONFIG";
            configBtn.Location = new Point(40, 165);
            configBtn.Size = new Size(80, 32);
            configBtn.Font = new Font("Segoe UI", 9, FontStyle.Bold);
            configBtn.BackColor = Color.White;
            configBtn.ForeColor = Color.Black;
            configBtn.FlatStyle = FlatStyle.Flat;
            configBtn.Cursor = Cursors.Hand;
            configBtn.FlatAppearance.BorderSize = 0;

            configBtn.Click += delegate { OpenTotemConfig(); };

            panel.Controls.Add(nameLabel);
            panel.Controls.Add(statusDot);
            panel.Controls.Add(statusText);
            panel.Controls.Add(infoLabel);
            panel.Controls.Add(configBtn);

            panel.Click += delegate 
            { 
                if (!panel.Controls.OfType<Button>().Any(b => b.ClientRectangle.Contains(panel.PointToClient(Cursor.Position))))
                {
                    ToggleTotem(panel); 
                }
            };

            return panel;
        }

        private void OpenTotemConfig()
        {
            var configForm = new Form();
            configForm.Text = "Configure Inventory Totem";
            configForm.Size = new Size(350, 200);
            configForm.StartPosition = FormStartPosition.CenterParent;
            configForm.FormBorderStyle = FormBorderStyle.FixedDialog;
            configForm.MaximizeBox = false;
            configForm.MinimizeBox = false;
            configForm.BackColor = Color.FromArgb(30, 30, 30);

            var yPos = 20;

            var infoLabel = new Label();
            infoLabel.Text = "Auto-places totem from slot 1 to offhand\nwhen opening inventory (E)\n\nOnly works when Minecraft is focused\n\n⚠️ Make sure your totem is in slot 1!";
            infoLabel.Location = new Point(20, yPos);
            infoLabel.Size = new Size(300, 100);
            infoLabel.ForeColor = Color.FromArgb(200, 200, 200);
            infoLabel.Font = new Font("Segoe UI", 9);
            configForm.Controls.Add(infoLabel);

            yPos += 110;

            var saveBtn = new Button();
            saveBtn.Text = "OK";
            saveBtn.Location = new Point(125, yPos);
            saveBtn.Size = new Size(100, 35);
            saveBtn.BackColor = Color.White;
            saveBtn.ForeColor = Color.Black;
            saveBtn.FlatStyle = FlatStyle.Flat;
            saveBtn.Font = new Font("Segoe UI", 10, FontStyle.Bold);
            saveBtn.FlatAppearance.BorderSize = 0;

            saveBtn.Click += delegate
            {
                configForm.Close();
            };

            configForm.Controls.Add(saveBtn);
            configForm.ShowDialog();
        }

        private void ToggleTotem(Panel panel)
        {
            inventoryTotemActive = !inventoryTotemActive;

            if (inventoryTotemActive)
            {
                panel.BackColor = activeColor;

                foreach (Control ctrl in panel.Controls)
                {
                    if (ctrl is Label && ctrl.Tag != null && ctrl.Tag.ToString() == "statusdot")
                        ctrl.BackColor = Color.White;
                    if (ctrl is Label && ctrl.Tag != null && ctrl.Tag.ToString() == "statustext")
                    {
                        ((Label)ctrl).Text = "Active";
                        ctrl.ForeColor = Color.White;
                    }
                    if (ctrl is Label && ctrl.Tag != null && ctrl.Tag.ToString() == "info")
                        ctrl.ForeColor = Color.FromArgb(200, 200, 200);
                    if (ctrl is Label && ctrl.Tag == null)
                        ctrl.ForeColor = Color.White;
                }

                var thread = new Thread(RunInventoryTotem);
                thread.IsBackground = true;
                thread.Start();
            }
            else
            {
                panel.BackColor = cardColor;

                foreach (Control ctrl in panel.Controls)
                {
                    if (ctrl is Label && ctrl.Tag != null && ctrl.Tag.ToString() == "statusdot")
                        ctrl.BackColor = Color.FromArgb(60, 60, 60);
                    if (ctrl is Label && ctrl.Tag != null && ctrl.Tag.ToString() == "statustext")
                    {
                        ((Label)ctrl).Text = "Inactive";
                        ctrl.ForeColor = Color.FromArgb(150, 150, 150);
                    }
                    if (ctrl is Label && ctrl.Tag != null && ctrl.Tag.ToString() == "info")
                        ctrl.ForeColor = Color.FromArgb(150, 150, 150);
                    if (ctrl is Label && ctrl.Tag == null)
                        ctrl.ForeColor = Color.White;
                }
            }
        }

        private Panel CreateModuleCard(string name, int x, int y, string moduleId)
