            configForm.Controls.Add(keybindText);
            yPos += 55;

            TextBox slot1Text = null;
            TextBox slot2Text = null;
            TextBox slot3Text = null;
            TextBox delayText = null;
            TextBox delay1Text = null;
            TextBox delay2Text = null;
            TextBox delay3Text = null;
            TextBox delay4Text = null;
            TextBox delay5Text = null;
            TextBox delay6Text = null;

            if (moduleId == "hitcrystal")
            {
                var slot1Label = new Label();
                slot1Label.Text = "Crystal Slot:";
                slot1Label.Location = new Point(20, yPos);
                slot1Label.AutoSize = true;
                slot1Label.ForeColor = Color.White;
                slot1Text = new TextBox();
                slot1Text.Location = new Point(20, yPos + 20);
                slot1Text.Size = new Size(350, 25);
                slot1Text.BackColor = Color.FromArgb(50, 50, 50);
                slot1Text.ForeColor = Color.White;
                slot1Text.BorderStyle = BorderStyle.FixedSingle;
                slot1Text.MaxLength = 10;
                configForm.Controls.Add(slot1Label);
                configForm.Controls.Add(slot1Text);
                yPos += 55;

                var slot2Label = new Label();
                slot2Label.Text = "Obsidian Slot:";
                slot2Label.Location = new Point(20, yPos);
                slot2Label.AutoSize = true;
                slot2Label.ForeColor = Color.White;
                slot2Text = new TextBox();
                slot2Text.Location = new Point(20, yPos + 20);
                slot2Text.Size = new Size(350, 25);
                slot2Text.BackColor = Color.FromArgb(50, 50, 50);
                slot2Text.ForeColor = Color.White;
                slot2Text.BorderStyle = BorderStyle.FixedSingle;
                slot2Text.MaxLength = 10;
                configForm.Controls.Add(slot2Label);
                configForm.Controls.Add(slot2Text);
                yPos += 55;

                AddDelayFields(configForm, ref yPos, "Delay 1 (place obsidian):", ref delay1Text);
                AddDelayFields(configForm, ref yPos, "Delay 2 (switch to crystal):", ref delay2Text);
                AddDelayFields(configForm, ref yPos, "Delay 3 (right click):", ref delay3Text);
                AddDelayFields(configForm, ref yPos, "Delay 4 (left click):", ref delay4Text);
            }
            else
            {
                var slot1Label = new Label();
                slot1Label.Text = "Anchor Slot:";
                slot1Label.Location = new Point(20, yPos);
                slot1Label.AutoSize = true;
                slot1Label.ForeColor = Color.White;
                slot1Text = new TextBox();
                slot1Text.Location = new Point(20, yPos + 20);
                slot1Text.Size = new Size(350, 25);
                slot1Text.BackColor = Color.FromArgb(50, 50, 50);
                slot1Text.ForeColor = Color.White;
                slot1Text.BorderStyle = BorderStyle.FixedSingle;
                slot1Text.MaxLength = 10;
                configForm.Controls.Add(slot1Label);
                configForm.Controls.Add(slot1Text);
                yPos += 55;

                var slot2Label = new Label();
                slot2Label.Text = "Glowstone Slot:";
                slot2Label.Location = new Point(20, yPos);
                slot2Label.AutoSize = true;
                slot2Label.ForeColor = Color.White;
                slot2Text = new TextBox();
                slot2Text.Location = new Point(20, yPos + 20);
                slot2Text.Size = new Size(350, 25);
                slot2Text.BackColor = Color.FromArgb(50, 50, 50);
                slot2Text.ForeColor = Color.White;
                slot2Text.BorderStyle = BorderStyle.FixedSingle;
                slot2Text.MaxLength = 10;
                configForm.Controls.Add(slot2Label);
                configForm.Controls.Add(slot2Text);
                yPos += 55;

                var slot3Label = new Label();
                slot3Label.Text = "Totem/Explode Slot:";
                slot3Label.Location = new Point(20, yPos);
                slot3Label.AutoSize = true;
                slot3Label.ForeColor = Color.White;
                slot3Text = new TextBox();
                slot3Text.Location = new Point(20, yPos + 20);
                slot3Text.Size = new Size(350, 25);
                slot3Text.BackColor = Color.FromArgb(50, 50, 50);
                slot3Text.ForeColor = Color.White;
                slot3Text.BorderStyle = BorderStyle.FixedSingle;
                slot3Text.MaxLength = 10;
                configForm.Controls.Add(slot3Label);
                configForm.Controls.Add(slot3Text);
                yPos += 55;

                if (moduleId != "airplace")
                {
                    var delayLabel = new Label();
                    delayLabel.Text = "Default Delay (ms):";
                    delayLabel.Location = new Point(20, yPos);
                    delayLabel.AutoSize = true;
                    delayLabel.ForeColor = Color.White;
                    delayText = new TextBox();
                    delayText.Location = new Point(20, yPos + 20);
                    delayText.Size = new Size(350, 25);
                    delayText.Text = "50";
                    delayText.BackColor = Color.FromArgb(50, 50, 50);
                    delayText.ForeColor = Color.White;
                    delayText.BorderStyle = BorderStyle.FixedSingle;
                    configForm.Controls.Add(delayLabel);
                    configForm.Controls.Add(delayText);
                    yPos += 55;
                }

                AddDelayFields(configForm, ref yPos, "Delay 1 (step 1):", ref delay1Text);
                AddDelayFields(configForm, ref yPos, "Delay 2 (step 2):", ref delay2Text);
                AddDelayFields(configForm, ref yPos, "Delay 3 (step 3):", ref delay3Text);
                AddDelayFields(configForm, ref yPos, "Delay 4 (step 4):", ref delay4Text);
                AddDelayFields(configForm, ref yPos, "Delay 5 (step 5):", ref delay5Text);
                AddDelayFields(configForm, ref yPos, "Delay 6 (step 6):", ref delay6Text);
            }

            if (moduleConfigs.ContainsKey(moduleId))
            {
                var config = moduleConfigs[moduleId];
                if (slot1Text != null) slot1Text.Text = GetKeyName(config.Slot1);
                if (slot2Text != null) slot2Text.Text = GetKeyName(config.Slot2);
                if (slot3Text != null) slot3Text.Text = GetKeyName(config.Slot3);
                if (delayText != null) delayText.Text = config.Delay.ToString();
                if (delay1Text != null) delay1Text.Text = config.DelayMs1.ToString();
                if (delay2Text != null) delay2Text.Text = config.DelayMs2.ToString();
                if (delay3Text != null) delay3Text.Text = config.DelayMs3.ToString();
                if (delay4Text != null) delay4Text.Text = config.DelayMs4.ToString();
                if (delay5Text != null) delay5Text.Text = config.DelayMs5.ToString();
                if (delay6Text != null) delay6Text.Text = config.DelayMs6.ToString();
            }

            var saveBtn = new Button();
            saveBtn.Text = "SAVE";
            saveBtn.Location = new Point(125, yPos + 20);
            saveBtn.Size = new Size(150, 35);
            saveBtn.BackColor = Color.White;
            saveBtn.ForeColor = Color.Black;
            saveBtn.FlatStyle = FlatStyle.Flat;
            saveBtn.Font = new Font("Segoe UI", 10, FontStyle.Bold);
            saveBtn.FlatAppearance.BorderSize = 0;

            string capturedModuleId = moduleId;
            TextBox capturedKeybind = keybindText;
            TextBox capturedSlot1 = slot1Text;
            TextBox capturedSlot2 = slot2Text;
            TextBox capturedSlot3 = slot3Text;
            TextBox capturedDelay = delayText;
            TextBox capturedDelay1 = delay1Text;
            TextBox capturedDelay2 = delay2Text;
            TextBox capturedDelay3 = delay3Text;
            TextBox capturedDelay4 = delay4Text;
            TextBox capturedDelay5 = delay5Text;
            TextBox capturedDelay6 = delay6Text;
            Form capturedForm = configForm;

            saveBtn.Click += delegate
            {
                try
                {
                    var config = new ModuleConfig();
                    config.Keybind = capturedKeybind.Text.Trim().ToLower();
                    config.KeybindCode = GetVKCode(config.Keybind);

                    if (config.KeybindCode == 0)
                    {
                        MessageBox.Show("Invalid keybind! Please use a single key.", "Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
                        return;
                    }

                    config.Slot1 = GetVKCode(capturedSlot1.Text.Trim().ToLower());
                    config.Slot2 = GetVKCode(capturedSlot2.Text.Trim().ToLower());
                    config.Slot3 = capturedSlot3 != null ? GetVKCode(capturedSlot3.Text.Trim().ToLower()) : 0;
                    config.Delay = capturedDelay != null ? int.Parse(capturedDelay.Text) : 50;

                    config.DelayMs1 = capturedDelay1 != null && !string.IsNullOrEmpty(capturedDelay1.Text) ? int.Parse(capturedDelay1.Text) : 0;
                    config.DelayMs2 = capturedDelay2 != null && !string.IsNullOrEmpty(capturedDelay2.Text) ? int.Parse(capturedDelay2.Text) : 0;
                    config.DelayMs3 = capturedDelay3 != null && !string.IsNullOrEmpty(capturedDelay3.Text) ? int.Parse(capturedDelay3.Text) : 0;
                    config.DelayMs4 = capturedDelay4 != null && !string.IsNullOrEmpty(capturedDelay4.Text) ? int.Parse(capturedDelay4.Text) : 0;
                    config.DelayMs5 = capturedDelay5 != null && !string.IsNullOrEmpty(capturedDelay5.Text) ? int.Parse(capturedDelay5.Text) : 0;
                    config.DelayMs6 = capturedDelay6 != null && !string.IsNullOrEmpty(capturedDelay6.Text) ? int.Parse(capturedDelay6.Text) : 0;

                    moduleConfigs[capturedModuleId] = config;
                    MessageBox.Show("Configuration saved!", "Success", MessageBoxButtons.OK, MessageBoxIcon.Information);
                    capturedForm.Close();
                }
                catch (Exception ex)
                {
                    MessageBox.Show("Error: " + ex.Message, "Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
                }
            };

            configForm.Controls.Add(saveBtn);
            configForm.ShowDialog();
        }

        private void AddDelayFields(Form form, ref int yPos, string labelText, ref TextBox delayBox)
        {
            var delayLabel = new Label();
            delayLabel.Text = labelText;
            delayLabel.Location = new Point(20, yPos);
            delayLabel.AutoSize = true;
            delayLabel.ForeColor = Color.White;
            delayLabel.Font = new Font("Segoe UI", 9);

            delayBox = new TextBox();
            delayBox.Location = new Point(200, yPos - 3);
            delayBox.Size = new Size(170, 25);
            delayBox.Text = "0";
            delayBox.BackColor = Color.FromArgb(50, 50, 50);
            delayBox.ForeColor = Color.White;
            delayBox.BorderStyle = BorderStyle.FixedSingle;

            form.Controls.Add(delayLabel);
            form.Controls.Add(delayBox);
            yPos += 30;
        }

        private string GetKeyName(int vkCode)
        {
            foreach (var pair in keyMap)
            {
                if (pair.Value == vkCode)
                    return pair.Key;
            }
            return "";
        }

        private void ToggleModule(string moduleId, Panel panel)
        {
            if (!moduleConfigs.ContainsKey(moduleId))
            {
                MessageBox.Show("Configure the module first by clicking CONFIG!", "Warning", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                return;
            }

            if (activeModules.ContainsKey(moduleId) && activeModules[moduleId])
            {
                activeModules[moduleId] = false;
                panel.BackColor = cardColor;

                foreach (Control ctrl in panel.Controls)
                {
                    if (ctrl is Label && ctrl.Tag != null && ctrl.Tag.ToString() == "statusdot")
                        ctrl.BackColor = Color.FromArgb(60, 60, 60);
                    if (ctrl is Label && ctrl.Tag != null && ctrl.Tag.ToString() == "statustext")
                    {
                        ((Label)ctrl).Text = "Inactive";
                        ctrl.ForeColor = Color.FromArgb(150, 150, 150);
                    }
                    if (ctrl is Label && ctrl.Tag == null)
                        ctrl.ForeColor = Color.White;
                }
            }
            else
            {
                if (!activeModules.ContainsKey(moduleId))
                    activeModules.Add(moduleId, true);
                else
                    activeModules[moduleId] = true;

                panel.BackColor = activeColor;

                foreach (Control ctrl in panel.Controls)
                {
                    if (ctrl is Label && ctrl.Tag != null && ctrl.Tag.ToString() == "statusdot")
                        ctrl.BackColor = Color.White;
                    if (ctrl is Label && ctrl.Tag != null && ctrl.Tag.ToString() == "statustext")
                    {
                        ((Label)ctrl).Text = "Active";
                        ctrl.ForeColor = Color.White;
                    }
                    if (ctrl is Label && ctrl.Tag == null)
                        ctrl.ForeColor = Color.White;
                }

                var config = moduleConfigs[moduleId];
                string capturedId = moduleId;
                var thread = new Thread(delegate()
                {
                    switch (capturedId)
                    {
                        case "airplace": RunAirplace(config); break;
                        case "single": RunSingle(config); break;
                        case "double": RunDouble(config); break;
                        case "hitcrystal": RunHitCrystal(config); break;
                    }
                });
                thread.IsBackground = true;
                thread.Start();

                if (moduleThreads.ContainsKey(moduleId))
                    moduleThreads[moduleId] = thread;
                else
                    moduleThreads.Add(moduleId, thread);
            }
        }
    }
}
